"""Parsing harvests from text."""
from harvests import Harvest


def _parse_line(line):
    field, kilos = line.split(",")
    return Harvest(field.strip(), int(kilos))


def parse_harvests(text):
    """Parse lines of 'field,kilos' into Harvest records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out
